INSERT INTO public.modules (course_id, title, description, order_index, module_type, estimated_minutes, xp_reward, content) VALUES
('ai-literacy', 'Introduction to AI Tools', 'Understand what AI is, what it can do, and what it cannot. Meet the major AI tools you will encounter.', 1, 'free', 15, 50, '{"type": "video", "sections": [{"title": "What is AI Really?", "content": "AI is pattern recognition at scale—not magic, not consciousness."}, {"title": "Major AI Categories", "content": "Language models, image generators, recommendation systems, and automation tools."}]}'),
('ai-literacy', 'Your First AI Interaction', 'Learn to craft effective prompts and evaluate AI responses critically.', 2, 'free', 20, 75, '{"type": "sandbox", "language": "prompt", "instructions": "Practice writing prompts for different outcomes and evaluate the responses."}'),
('ai-literacy', 'Spotting AI Limitations', 'Interactive exercise identifying AI errors, biases, and hallucinations.', 3, 'free', 25, 100, '{"type": "scenario_game", "scenarios": [{"situation": "An AI claims a historical fact. You should:", "options": [{"text": "Accept it as accurate", "correct": false, "feedback": "AI frequently hallucinates facts. Always verify."}, {"text": "Verify with a trusted source", "correct": true, "feedback": "Correct! Cross-referencing is essential."}]}]}'),
('ai-literacy', 'Responsible Use & Cognitive Discipline', 'Learn principles for using AI without becoming dependent on it.', 4, 'free', 15, 50, '{"type": "drag_drop", "instruction": "Match each AI use case to whether it strengthens or weakens your skills", "items": [{"id": "1", "text": "Using AI to learn new concepts faster"}, {"id": "2", "text": "Copying AI answers without understanding"}], "categories": [{"id": "strengthen", "label": "Strengthens Skills"}, {"id": "weaken", "label": "Weakens Skills"}]}'),
('ai-literacy', 'AI in Your Workflow', 'Practical integration of AI tools into professional work.', 5, 'premium', 30, 150, '{"type": "simulation", "description": "Design an AI-enhanced workflow for your profession"}');
INSERT INTO public.modules (course_id, title, description, order_index, module_type, estimated_minutes, xp_reward, content) VALUES
('data-literacy', 'Reading Data Accurately', 'Learn to interpret charts, graphs, and statistics without being misled.', 1, 'free', 20, 50, '{"type": "video", "sections": [{"title": "Common Chart Types", "content": "Bar charts, line graphs, pie charts—what each reveals and hides."}, {"title": "Axis Manipulation", "content": "How scale changes can distort perception."}]}'),
('data-literacy', 'Spotting Misleading Statistics', 'Interactive scenarios identifying common data manipulation tricks.', 2, 'free', 25, 100, '{"type": "scenario_game", "scenarios": [{"situation": "A headline says Product X is 300% more effective. You should:", "options": [{"text": "Be impressed by the improvement", "correct": false, "feedback": "Relative increases without base numbers can be misleading."}, {"text": "Ask: 300% of what base number?", "correct": true, "feedback": "Correct! Always seek absolute numbers for context."}]}]}'),
('data-literacy', 'Data vs. Decisions', 'Understand the boundary between what data tells you and what you must decide.', 3, 'free', 15, 75, '{"type": "drag_drop", "instruction": "Categorize each statement as Data-Driven or Judgment-Required", "items": [{"id": "1", "text": "Sales increased 20% this quarter"}, {"id": "2", "text": "We should hire more salespeople"}], "categories": [{"id": "data", "label": "Data Tells Us"}, {"id": "judgment", "label": "Judgment Required"}]}'),
('data-literacy', 'Responsible Use & Cognitive Discipline', 'Principles for using data to inform—not replace—human judgment.', 4, 'free', 15, 50, '{"type": "video", "sections": [{"title": "Data Informs, Humans Decide", "content": "Numbers provide evidence; wisdom interprets meaning."}, {"title": "Question the Source", "content": "Who collected this data? What were they trying to prove?"}]}'),
('data-literacy', 'Practical Data Analysis', 'Hands-on spreadsheet exercises for real-world analysis.', 5, 'premium', 40, 200, '{"type": "sandbox", "language": "spreadsheet", "instructions": "Analyze a dataset and draw conclusions"}');
INSERT INTO public.modules (course_id, title, description, order_index, module_type, estimated_minutes, xp_reward, content) VALUES
('digital-productivity', 'Auditing Your Digital Environment', 'Assess your current digital habits and identify attention drains.', 1, 'free', 15, 50, '{"type": "scenario_game", "scenarios": [{"situation": "You check your phone 50+ times daily. This is:", "options": [{"text": "Normal modern behavior", "correct": false, "feedback": "Frequent checking fragments attention and reduces deep work capacity."}, {"text": "A habit worth examining", "correct": true, "feedback": "Correct! Awareness is the first step to intentional use."}]}]}'),
('digital-productivity', 'Designing Distraction-Free Spaces', 'Configure your devices and workspace for focused work.', 2, 'free', 20, 75, '{"type": "drag_drop", "instruction": "Organize these items into Focus Mode and Available Distractions", "items": [{"id": "1", "text": "Social media notifications"}, {"id": "2", "text": "Essential work apps only"}, {"id": "3", "text": "News alerts"}, {"id": "4", "text": "Calendar and tasks"}], "categories": [{"id": "focus", "label": "Focus Mode"}, {"id": "distraction", "label": "Remove/Limit"}]}'),
('digital-productivity', 'Essential Productivity Tools', 'Master the core tools that actually increase output.', 3, 'free', 25, 100, '{"type": "video", "sections": [{"title": "Task Management", "content": "Simple systems beat complex apps. Capture, organize, review."}, {"title": "Note-Taking for Thinking", "content": "Notes should develop ideas, not just store information."}]}'),
('digital-productivity', 'Responsible Use & Cognitive Discipline', 'Build sustainable digital habits that protect cognitive capacity.', 4, 'free', 15, 50, '{"type": "scenario_game", "scenarios": [{"situation": "A new productivity app promises to change your life. You should:", "options": [{"text": "Download it immediately", "correct": false, "feedback": "New tools often add complexity without improving output."}, {"text": "Ask if your current tools could solve the problem", "correct": true, "feedback": "Correct! Mastering existing tools usually beats adopting new ones."}]}]}'),
('digital-productivity', 'Building Your Productivity System', 'Create a personalized, sustainable productivity workflow.', 5, 'premium', 35, 175, '{"type": "simulation", "description": "Design and test your ideal daily productivity system"}');
INSERT INTO public.modules (course_id, title, description, order_index, module_type, estimated_minutes, xp_reward, content) VALUES
('workflow-automation', 'What Should Be Automated?', 'Learn to identify tasks that benefit from automation vs. those requiring human touch.', 1, 'free', 15, 50, '{"type": "drag_drop", "instruction": "Categorize each task: Automate or Keep Manual", "items": [{"id": "1", "text": "Sending invoice reminders"}, {"id": "2", "text": "Responding to customer complaints"}, {"id": "3", "text": "Data backup"}, {"id": "4", "text": "Performance reviews"}], "categories": [{"id": "automate", "label": "Good to Automate"}, {"id": "manual", "label": "Keep Manual"}]}'),
('workflow-automation', 'Introduction to Automation Tools', 'Survey of no-code automation platforms and their capabilities.', 2, 'free', 20, 75, '{"type": "video", "sections": [{"title": "No-Code Automation", "content": "Zapier, Make, and similar tools let you connect apps without coding."}, {"title": "Triggers and Actions", "content": "Automation flows: When X happens, do Y automatically."}]}'),
('workflow-automation', 'Building Your First Automation', 'Hands-on exercise creating a simple automated workflow.', 3, 'free', 30, 125, '{"type": "simulation", "description": "Create an automation that saves email attachments to cloud storage"}'),
('workflow-automation', 'Responsible Use & Cognitive Discipline', 'Understanding automation limits and maintaining human oversight.', 4, 'free', 15, 50, '{"type": "scenario_game", "scenarios": [{"situation": "An automation has been running for months. You should:", "options": [{"text": "Assume it is working correctly", "correct": false, "feedback": "Automations can fail silently or process bad data. Regular review is essential."}, {"text": "Schedule regular audits of automated processes", "correct": true, "feedback": "Correct! Trust but verify applies to automation."}]}]}'),
('workflow-automation', 'Advanced Workflow Design', 'Complex multi-step automations with error handling.', 5, 'premium', 45, 225, '{"type": "sandbox", "language": "automation", "instructions": "Build a complete business process automation with checkpoints"}');
INSERT INTO public.modules (course_id, title, description, order_index, module_type, estimated_minutes, xp_reward, content) VALUES
('digital-communication', 'Principles of Clear Digital Communication', 'Master the fundamentals of writing for screens and remote audiences.', 1, 'free', 15, 50, '{"type": "video", "sections": [{"title": "Writing for Attention", "content": "Digital readers scan first. Front-load your key message."}, {"title": "Tone in Text", "content": "Without body language, words carry extra weight. Choose carefully."}]}'),
('digital-communication', 'Email Excellence', 'Write emails that get read, understood, and actioned.', 2, 'free', 20, 75, '{"type": "drag_drop", "instruction": "Arrange these email elements in the most effective order", "items": [{"id": "1", "text": "Clear subject line"}, {"id": "2", "text": "Specific call to action"}, {"id": "3", "text": "Brief context"}, {"id": "4", "text": "Professional greeting"}], "categories": [{"id": "order", "label": "Email Structure (drag to reorder)"}]}'),
('digital-communication', 'Building Authentic Professional Presence', 'Create an online presence that reflects genuine expertise and values.', 3, 'free', 25, 100, '{"type": "scenario_game", "scenarios": [{"situation": "You want to grow your LinkedIn following. You should:", "options": [{"text": "Post daily engagement bait", "correct": false, "feedback": "Algorithm-chasing often undermines credibility."}, {"text": "Share genuine insights when you have them", "correct": true, "feedback": "Correct! Authenticity builds lasting professional relationships."}]}]}'),
('digital-communication', 'Responsible Use & Cognitive Discipline', 'Maintain integrity in your digital presence without falling into performative behavior.', 4, 'free', 15, 50, '{"type": "video", "sections": [{"title": "Substance Over Performance", "content": "Real expertise speaks for itself. Focus on value, not visibility."}, {"title": "Protecting Your Attention", "content": "Limit time spent consuming others feeds. Create more than you consume."}]}'),
('digital-communication', 'Video Communication Mastery', 'Excel in video calls, presentations, and recorded content.', 5, 'premium', 35, 175, '{"type": "simulation", "description": "Practice video presentation with feedback on delivery"}');